package mobilepq
import("bytes";"context";"errors";"net";"sync";"testing";"time")
// These are lifecycle tests, not cryptographic evidence. Rust tests separately
// exercise real two-peer exchanges against the pinned Rosenpass implementation.
type testProtocol struct{mu sync.Mutex;key []byte;calls,closes int;closed bool}
func(p *testProtocol)Step(kind uint32,input []byte)(Event,error){p.mu.Lock();defer p.mu.Unlock();if p.closed{return Event{},ErrStopped};p.calls++;if kind==0{return Event{Wait:10*time.Millisecond},nil};switch string(input){case "bad":return Event{},ErrPacket;case "expire":return Event{Expired:true},nil;case "fatal":return Event{},errors.New("not-for-logs");case "oversized":return Event{Key:make([]byte,33)},nil};p.key=bytes.Repeat([]byte{byte(p.calls%200+1)},32);return Event{Key:p.key},nil}
func(p *testProtocol)Close()error{p.mu.Lock();defer p.mu.Unlock();p.closes++;p.closed=true;return nil}
type testTarget struct{mu sync.Mutex;keys [][]byte;revokes int;revoked bool;entered,release chan struct{};failRevoke bool}
func(p *testTarget)ApplyPQKey(key []byte)error{if p.entered!=nil{close(p.entered);<-p.release};p.mu.Lock();defer p.mu.Unlock();if p.revoked{return ErrStopped};p.keys=append(p.keys,append([]byte(nil),key...));return nil}
func(p *testTarget)RevokePQKey()error{p.mu.Lock();defer p.mu.Unlock();p.revoked=true;p.revokes++;if p.failRevoke{return errors.New("private-native-details")};return nil}
func fixture(t *testing.T)(*Controller,*testProtocol,*testTarget,net.Conn){t.Helper();a,b:=net.Pipe();p:=&testProtocol{};target:=&testTarget{};c,err:=New(context.Background(),p,target,func(context.Context)(net.Conn,error){return a,nil});if err!=nil{t.Fatal(err)};c.timeout=time.Second;t.Cleanup(func(){b.Close();c.Close()});return c,p,target,b}
func begin(c *Controller)<-chan error{done:=make(chan error,1);go func(){done<-c.Start()}();return done}
func await(t *testing.T,done <-chan error,wantError bool){t.Helper();select{case err:=<-done:if (err!=nil)!=wantError{t.Fatalf("start result %v",err)};case <-time.After(2*time.Second):t.Fatal("startup did not settle")}}
func send(t *testing.T,wire net.Conn,text string){t.Helper();wire.SetWriteDeadline(time.Now().Add(time.Second));if _,err:=wire.Write([]byte(text));err!=nil{t.Fatal(err)}}
func eventually(t *testing.T,predicate func()bool){t.Helper();end:=time.Now().Add(time.Second);for !predicate(){if time.Now().After(end){t.Fatal("lifecycle did not settle")};time.Sleep(time.Millisecond)}}
func TestAuthenticatedAdoptionRekeyAndExpiry(t *testing.T){c,p,target,wire:=fixture(t);done:=begin(c);if c.Ready(){t.Fatal("ready before authenticated key")};send(t,wire,"bad");if c.Ready(){t.Fatal("bad datagram adopted")};send(t,wire,"key");await(t,done,false);if !c.Ready(){t.Fatal("authenticated key missing")};eventually(t,func()bool{p.mu.Lock();defer p.mu.Unlock();return len(p.key)==32&&bytes.Equal(p.key,make([]byte,32))});send(t,wire,"rekey");eventually(t,func()bool{target.mu.Lock();defer target.mu.Unlock();return len(target.keys)==2});target.mu.Lock();if bytes.Equal(target.keys[0],target.keys[1]){t.Fatal("rekey lost")};target.mu.Unlock();send(t,wire,"expire");eventually(t,func()bool{return !c.Ready()});if err:=c.Close();err!=nil{t.Fatal(err)};if !errors.Is(c.Err(),ErrExpired){t.Fatal(c.Err())};target.mu.Lock();defer target.mu.Unlock();if !target.revoked||target.revokes!=1{t.Fatal("expired peer not revoked exactly once")}}
func TestCancelDuringAdoptionCannotBecomeReady(t *testing.T){c,_,target,wire:=fixture(t);target.entered=make(chan struct{});target.release=make(chan struct{});done:=begin(c);send(t,wire,"key");<-target.entered;closed:=make(chan struct{});go func(){c.Close();close(closed)}();eventually(t,func()bool{return c.ctx.Err()!=nil});close(target.release);await(t,done,true);<-closed;if c.Ready(){t.Fatal("cancelled key adopted")};target.mu.Lock();defer target.mu.Unlock();if !target.revoked{t.Fatal("cancel did not revoke")}}
func TestCancelDuringDialClosesLateSocket(t *testing.T){p:=&testProtocol{};target:=&testTarget{};entered,release:=make(chan struct{}),make(chan struct{});a,b:=net.Pipe();defer b.Close();c,_:=New(context.Background(),p,target,func(context.Context)(net.Conn,error){close(entered);<-release;return a,nil});done:=begin(c);<-entered;closed:=make(chan struct{});go func(){c.Close();close(closed)}();eventually(t,func()bool{return c.ctx.Err()!=nil});close(release);await(t,done,true);<-closed;if c.Ready(){t.Fatal("late socket adopted")};b.SetReadDeadline(time.Now().Add(time.Second));if _,err:=b.Read(make([]byte,1));err==nil{t.Fatal("late socket survived")}}
func TestRejectedEventsAndNeverStartedClose(t *testing.T){for _,bad:=range []string{"fatal","oversized"}{t.Run(bad,func(t *testing.T){c,_,_,wire:=fixture(t);done:=begin(c);send(t,wire,bad);await(t,done,true);if c.Ready(){t.Fatal("invalid event adopted")}})};c,p,target,_:=fixture(t);c.Close();c.Close();if err:=c.Start();err==nil{t.Fatal("closed owner restarted")};if p.closes!=1||target.revokes!=1{t.Fatal("never-started close not joined")}}
func TestRepeatedConcurrentCloseJoinsExactlyOnce(t *testing.T){c,p,target,wire:=fixture(t);done:=begin(c);send(t,wire,"key");await(t,done,false);var group sync.WaitGroup;for i:=0;i<20;i++{group.Add(1);go func(){defer group.Done();c.Close()}()};group.Wait();if c.Ready()||p.closes!=1||target.revokes!=1{t.Fatal("close did not join exactly once")}}
func TestCleanupFailureIsNotSuccess(t *testing.T){c,_,target,wire:=fixture(t);target.failRevoke=true;done:=begin(c);send(t,wire,"key");await(t,done,false);if err:=c.Close();!errors.Is(err,ErrCleanup){t.Fatal("unconfirmed cleanup reported success",err)};if c.Ready(){t.Fatal("cleanup failure retained ready")}}
func TestNilConnectionAndTimeoutNeverAdopt(t *testing.T){p:=&testProtocol{};target:=&testTarget{};c,_:=New(context.Background(),p,target,func(context.Context)(net.Conn,error){return nil,nil});await(t,begin(c),true);if err:=c.Close();err!=nil{t.Fatal(err)};c,_,_,_ =fixture(t);c.timeout=10*time.Millisecond;await(t,begin(c),true);if c.Ready(){t.Fatal("timeout reported ready")}}
